// ===================== FINANCE (dedicated main tab) =====================
// Built on the shared keyed ledger (S.L) and running cost accruals (S.cc). Energy costs arrive from Energy Management via S.cc —
// never re-posted here. All tariffs, fees and prices are ILLUSTRATIVE assumptions, not Cairo Airport figures.
const hm2t = s => {const [h, m] = String(s).split(':').map(Number); return (h * 60 + (m || 0)) - 360}, t2hm = t => loc(t);
const recog = e => RECOG.includes(e.status);
const revTerm = e => {const r = S.rot[e.rot]; return r && STAND[r.stand] ? STAND[r.stand].term || 'Airside' : 'Airport-wide'};

// ---------- 1 · Financial Overview ----------
VIEWS['fin.overview'] = {sub: 'Revenue, operating expenses, net operating result and outstanding charges from the simulated ledger — illustrative tariffs, not actual airport accounts.',
  html: () => `<div data-live="foKpi"></div>
  <div class="g g2" style="margin-top:12px"><div class="card"><div class="ch">Cumulative revenue, expenses & operating result (sim day)</div><div data-live="foTrend"></div></div><div class="card"><div class="ch">Recognised revenue by hour & source</div><div data-live="foHourly"></div></div></div>
  <div class="g g3" style="margin-top:12px"><div class="card"><div class="ch">Revenue mix</div><div data-live="pnlRevCat"></div></div><div class="card"><div class="ch">Expense mix</div><div data-live="foCost"></div></div><div class="card"><div class="ch">Cash, receivables & estimates</div><div data-live="pnlStatus"></div></div></div>
  <div class="card" style="margin-top:12px"><div class="ch">Latest transactions<span class="sp"></span><button class="btn" onclick="go('fin','tx')">Search all →</button></div><div data-live="foTx" class="tw"></div></div>`};
LIVE.foKpi = () => {const p = pnl(S), m = p.memo, b = BASE.snap.filter(x => x.t <= S.t).pop() || {op: 0}, out = (m.invoiced || 0) + (m.accrued || 0) + (m.disputed || 0) + (m.deferred || 0);
  return `<div class="kp">${kpiTile('Total revenue (recognised)', mk(p.gross), 'accrued + invoiced + paid + disputed', "go('fin','revenue')")}${kpiTile('Operating expenses', mk(p.costTot), 'airport-borne incl. energy', "go('fin','opex')")}${kpiTile('Net operating result', mk(p.op), p.net ? Math.round(100 * p.op / p.net) + '% operating margin' : '', "go('fin','pnl')", p.op >= 0 ? 'pos' : 'neg')}${kpiTile('Outstanding charges', mk(out), 'invoiced, accrued, disputed & deferred', "go('fin','tx')")}
  ${kpiTile('Cash collected', mk(m.paid || 0), Math.round(100 * (m.paid || 0) / (p.gross || 1)) + '% of revenue', '', 'pos')}${kpiTile('Disputed', mk(m.disputed || 0), S.cfg.disputeProvisionPct + '% provision ' + mk(p.provision), '', m.disputed ? 'neg' : '')}${kpiTile('vs forecast', (p.op - b.op >= 0 ? '+' : '') + mk(p.op - b.op), 'operating result vs baseline run', '', p.op - b.op >= 0 ? 'pos' : 'neg')}${kpiTile('Estimated revenue still to come', mk(futureRevenue(S)), 'rest of day — forecast, not recognised')}</div>`};
LIVE.foTrend = () => lineChart('c-fo', [{name: 'Revenue (net)', color: 'var(--s2)', pts: S.snap.map(x => [x.t, x.rev])}, {name: 'Operating expenses', color: 'var(--s5)', pts: S.snap.map(x => [x.t, x.cost])}, {name: 'Operating result', color: 'var(--s1)', pts: S.snap.map(x => [x.t, x.op])}, {name: 'Result — forecast', color: 'var(--mu)', pts: BASE.snap.filter(x => x.t <= S.t).map(x => [x.t, x.op]), dash: 1}], {fx: loc, fy: v => mk(v)});
const revGroupOf = cat => {const g = REV_GROUPS.find(g => g[1].includes(cat)); return g ? g[0] : 'Other'};
LIVE.foHourly = () => {const keys = REV_GROUPS.map(g => g[0]), rows = []; for (let t = 0; t < Math.min(S.t, DAY_END); t += 60) rows.push({x: pad(hourOf(t)), label: pad(hourOf(t)) + ':00', v: {}});
  for (const e of S.L) if (e.kind == 'rev' && e.payee == 'Airport' && recog(e)) {const r = rows[Math.floor(Math.max(0, e.t - 1) / 60)]; if (r) {const k = revGroupOf(e.cat); r.v[k] = (r.v[k] || 0) + e.usd}}
  return stackBars('c-foh', rows, keys, keys.map((k, i) => `var(--s${i % 8 + 1})`), {names: keys, fy: v => mk(v)}) + '<p class="note">Posted when charged (landing and stand charges at off-block, commercial income hourly).</p>'};
LIVE.foCost = () => {const p = pnl(S); return hbars(Object.entries(p.cost).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([k, v], i) => [k, v, `var(--s${i % 8 + 1})`]))};
LIVE.foTx = () => {const l = S.L.slice(-12).reverse(); return `<table><tr><th>ID</th><th>Time</th><th>Type</th><th>Category</th><th>Description</th><th>Payer → receiver / bearer</th><th class="n">Amount</th><th>Status</th></tr>${l.map(e => `<tr><td class="mu">${e.id}</td><td>${loc(e.t)}</td><td>${e.kind == 'rev' ? bd('revenue', 'ok') : bd('cost', 'wn')}</td><td class="sm">${e.cat}</td><td class="sm">${esc(e.desc)}</td><td class="sm">${e.kind == 'rev' ? esc(e.payer) + ' → ' + esc(e.payee) : esc(e.bearer)}</td><td class="n">${money(e.usd, 2)}</td><td>${bd(e.status, e.status == 'paid' ? 'ok' : e.status == 'disputed' ? 'cr' : '')}</td></tr>`).join('')}</table>`};

// ---------- 2 · Revenue Sources ----------
REV_GROUPS[6][0] = 'Passenger-related charges';
REV_GROUPS.splice(7, 0, ['Terminal services (lounges, fast-track)', ['Terminal services']]);
REV_GROUPS.push(['Emergency diversion services', ['Diversion handling']]);
VIEWS['fin.revenue'] = {sub: 'Landing, parking, overstay, passenger-related, ground handling, terminal services and configurable commercial streams — who pays, who receives, status and tariff reference.',
  html: () => VIEWS['biz.revenue'].html() + `<div class="card" style="margin-top:12px"><div class="ch">Configurable revenue streams<span class="sp"></span><button class="btn" onclick="go('fin','config')">Edit streams & rates →</button></div><div data-live="frCustom" class="tw"></div></div>`};
LIVE.frCustom = () => {const o = OTHER_COM.map(([k, n, payer, cat]) => [n, payer, cat, S.cfg.other[k] || 0, 'standard']), cu = (S.cfg.custom || []).map(x => [x.name, x.payer, 'Other commercial', x.usdDay, 'user-defined']);
  return `<table><tr><th>Stream</th><th>Payer</th><th>Category</th><th class="n">Rate / day</th><th class="n">Recognised today</th><th>Type</th></tr>${o.concat(cu).map(([n, p, c, d, ty]) => `<tr><td>${esc(n)}</td><td class="sm">${esc(p)}</td><td class="sm">${c}</td><td class="n">${money(d)}</td><td class="n">${money(ledSum(S, e => e.kind == 'rev' && e.payee == 'Airport' && e.desc.startsWith(n + ' ')))}</td><td>${bd(ty, ty == 'standard' ? '' : 'in')}</td></tr>`).join('')}</table>
  <p class="note">Accrued hourly as rate ÷ 24 (contract assumption). User-defined streams are added in Rates, Fees & Currency.</p>`};

// ---------- 3 · Operating Expenses ----------
VIEWS['fin.opex'] = {sub: 'Electricity, water, fuel, maintenance, staffing, equipment, ground vehicles, baggage systems and emergency response — each with its formula. Energy lines come from Energy Management (same meters, counted once).',
  html: () => VIEWS['biz.costs'].html()};

// ---------- 4 · Aircraft Overstay Calculator ----------
const OVQ = {rot: '', type: 'A320', op: 'sched', allowed: '14:00', off: '15:10', party: 'Airline', stand: 'contact'};
function ovLoad(id) {const r = S.rot[id]; if (!r) return; const al = r.allowedOff ?? (r.dep ? Math.max(r.dep.std, r.onBlk + AC_TYPES[r.type].mtt) : S.t);
  Object.assign(OVQ, {rot: id, type: r.type, op: r.op, allowed: t2hm(al), off: t2hm(r.offBlk ?? Math.max(S.t, al)), party: dominantParty(r).party == '—' ? 'Airline' : dominantParty(r).party, stand: STAND[r.stand].kind == 'contact' ? 'contact' : 'remote'}); renderPage()}
VIEWS['fin.overstay'] = {sub: 'Additional charge when an aircraft occupies a stand beyond its allowed off-block time — the same rule set the simulation uses when it bills at off-block.',
  html: () => {const sel = (k, opts) => `<select onchange="OVQ.${k}=this.value;live(true)">${opts.map(o => Array.isArray(o) ? o : [o, o]).map(([v, n]) => `<option value="${v}" ${OVQ[k] == v ? 'selected' : ''}>${n}</option>`).join('')}</select>`;
    const onStand = S.R.filter(r => r.dep && r.onBlk != null && r.onBlk >= 0 && (r.offBlk == null || r.offBlk >= 0)).sort((a, b) => (a.offBlk != null) - (b.offBlk != null) || b.onBlk - a.onBlk).slice(0, 60);
    return `<div class="g" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr)"><div class="card"><div class="ch">Calculator</div>
    <div class="calc"><label>Load a simulated aircraft<select onchange="ovLoad(this.value)"><option value="">— manual entry —</option>${onStand.map(r => `<option value="${r.id}" ${OVQ.rot == r.id ? 'selected' : ''}>${fid(r)} ${r.reg} · ${r.stand}${r.offBlk == null ? ' (on stand)' : ''}</option>`).join('')}</select></label>
    <label>Aircraft type${sel('type', Object.keys(AC_TYPES).map(k => [k, `${k} (code ${AC_TYPES[k].code}, ${AC_TYPES[k].mtow} t)`]))}</label><label>Operation${sel('op', ['sched', 'charter', 'private', 'diversion'])}</label><label>Stand${sel('stand', [['contact', 'Contact (bridge + 400 Hz)'], ['remote', 'Remote']])}</label>
    <label>Allowed off-block (scheduled departure)<input type="time" value="${OVQ.allowed}" onchange="OVQ.allowed=this.value;live(true)"></label><label>Actual / expected off-block<input type="time" value="${OVQ.off}" onchange="OVQ.off=this.value;live(true)"></label>
    <label>Delay caused by${sel('party', ['Airline', 'Ground handler', 'Weather', 'Airport', 'ANSP'])}</label></div>
    <p class="note">Grace ${S.cfg.overstay.graceMin} min, charged per started 15 min: code B $${S.cfg.overstay.usdPer15.B} · C $${S.cfg.overstay.usdPer15.C} · E $${S.cfg.overstay.usdPer15.E} (illustrative — edit in Rates, Fees & Currency).</p></div>
    <div class="card"><div class="ch">Result</div><div data-live="ovRes"></div></div></div>
    <div class="card" style="margin-top:12px"><div class="ch">All stand occupations today — parking, overstay & responsibility</div><div data-live="parkTab" class="tw" style="max-height:60vh"></div></div>`}};
function ovCalcQ() {return ovQuote(S, {type: OVQ.type, op: OVQ.op, allowed: hm2t(OVQ.allowed), off: hm2t(OVQ.off), party: OVQ.party})}
LIVE.ovRes = () => {const q = ovCalcQ(), c = S.cfg, gpu = OVQ.stand == 'contact' ? q.over / 60 * c.gpuKw * c.elec.offpeakEgp / c.fx + q.over / 60 * c.pbbUsdHr * 0 : 0, rec = q.status == 'invoiced';
  return `<div class="res"><div class="mu sm">Overstay charge</div><div class="big ${rec ? '' : 'mu'}">${money(q.usd)}</div><div class="row" style="margin-top:4px">${bd(rec ? 'INVOICED to ' + q.payer : 'WAIVED — not revenue', rec ? 'ok' : '')}${q.why ? `<span class="sm mu">${esc(q.why)}</span>` : ''}</div></div>
  <table style="margin-top:10px"><tr><td>Time beyond allowed off-block</td><td class="n">${Math.round(Math.max(0, hm2t(OVQ.off) - hm2t(OVQ.allowed)))} min</td></tr><tr><td>Less grace period</td><td class="n">${c.overstay.graceMin} min</td></tr><tr><td>Chargeable</td><td class="n">${Math.round(q.over)} min → ${q.blocks} × 15-min blocks</td></tr><tr><td>Rate (code ${q.code})</td><td class="n">${money(q.rate)} / block</td></tr><tr><td>Payer → receiver</td><td class="n">${rec ? q.payer + ' → Airport' : '—'}</td></tr></table>
  <p class="formula" style="margin-top:8px">${esc(q.formula)}</p>
  <p class="note">Revenue ≠ profit: the charge compensates for a blocked stand. ${OVQ.stand == 'contact' ? `Extra 400 Hz energy for the overstay ≈ ${money(gpu)} (cost to the airport, metered in Energy Management). ` : ''}Arrivals moved off the stand are an opportunity cost (memo, not booked). ${OVQ.rot ? 'For the loaded aircraft the simulation posts this charge itself at off-block — the calculator never posts entries.' : ''}</p>`};

// ---------- 5 · Aircraft Technical Failure ----------
const DFQ = {rot: '', type: 'HYD', cause: ''};
function dfEstimate(rid, type, cause) {const r = S.rot[rid], D = DEFECTS[type]; if (!r || !D) return null;
  const d = {r: rid, type, ...deep(D), cause: cause || D.cause, t: S.t, partsUsd: 0, estReady: S.t + D.steps.reduce((a, s) => a + s[1], 0) + 10, towUsd: D.tow ? 650 : 0};
  return defectImpact(S, d)}
function dfRecord() {if (!can()) return; const r = S.rot[DFQ.rot]; if (!r) return toast('Select an aircraft');
  if (!confirm(`Record ${DEFECTS[DFQ.type].name} on ${fid(r)} ${r.reg}?\n\nRaises a work order in Assets & Maintenance and is written to the audit log.`)) return;
  const d = reportDefect(S, r.id, DFQ.type, role); if (!d) return toast('Aircraft already has an open defect');
  if (DFQ.cause && DFQ.cause != d.cause) {d.log.push([S.t, `Cause allocation set to “${DFQ.cause}” by ${role} (was “${d.cause}”)`]); d.cause = DFQ.cause}
  audit(`Technical failure recorded ${d.wo} ${fid(r)} — cause ${d.cause}`); toast(d.wo + ' raised'); DFQ.rot = ''; renderPage()}
VIEWS['fin.defect'] = {sub: 'Record a technical failure, estimate repair and operational costs, identify the responsible party and keep airport expenses separate from airline (and other parties\') expenses.',
  html: () => {const cand = S.R.filter(r => r.dep && r.onBlk != null && r.offBlk == null && !r.mx && r.op != 'diversion'), D = DEFECTS[DFQ.type];
    if (!cand.some(r => r.id == DFQ.rot)) DFQ.rot = cand.length ? cand[0].id : '';
    return `<div class="g" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr)"><div class="card"><div class="ch">Record an incident</div><div class="calc">
    <label>Aircraft on stand<select onchange="DFQ.rot=this.value;live(true)"><option value="">— select —</option>${cand.map(r => `<option value="${r.id}" ${DFQ.rot == r.id ? 'selected' : ''}>${fid(r)} ${r.reg} · ${r.type} · ${r.stand} · STD ${loc(r.dep.std)}</option>`).join('')}</select></label>
    <label>Failure<select onchange="DFQ.type=this.value;DFQ.cause='';renderPage()">${Object.entries(DEFECTS).map(([k, x]) => `<option value="${k}" ${DFQ.type == k ? 'selected' : ''}>${x.ata} ${x.name} (${x.sev})</option>`).join('')}</select></label>
    <label>Cause allocation<select onchange="DFQ.cause=this.value;live(true)">${Object.keys(CAUSE_ALLOC).map(k => `<option ${(DFQ.cause || D.cause) == k ? 'selected' : ''}>${k}</option>`).join('')}</select></label></div>
    <div class="row" style="margin-top:10px"><button class="btn dg" onclick="dfRecord()">Record incident & raise work order</button><span class="sm mu">Release to service still needs a Certifying Engineer.</span></div>
    <div data-live="dfAlloc" style="margin-top:10px"></div></div><div class="card"><div class="ch">Cost estimate (before recording)</div><div data-live="dfEst"></div></div></div>
    <div class="card" style="margin-top:12px"><div class="ch">Recorded technical failures — who bears what</div><div data-live="dfTab" class="tw"></div></div>`}};
LIVE.dfAlloc = () => {const A = CAUSE_ALLOC[DFQ.cause || DEFECTS[DFQ.type].cause]; return `<table class="sm"><tr><td>Bears the cost first</td><td><b>${A.bearer}</b></td></tr><tr><td>Possible recovery from</td><td>${A.reimb} (${A.pct}% assumption — estimate, not recognised)</td></tr>${A.contingent ? `<tr><td>Contingent</td><td class="neg">${A.contingent} — only if liability is established</td></tr>` : ''}<tr><td colspan="2" class="mu">${esc(A.note)}</td></tr></table>`};
const dfSplit = im => {const by = {}; for (const [n, v, nat, b] of im.rows) if (v > 0 && nat != 'contractual') by[b] = (by[b] || 0) + v; return by};
LIVE.dfEst = () => {if (!DFQ.rot) return '<div class="empty">Select an aircraft to estimate</div>'; const im = dfEstimate(DFQ.rot, DFQ.type, DFQ.cause); if (!im) return '<div class="empty">Aircraft no longer on stand</div>'; const by = dfSplit(im);
  return `<table><tr><th>Item</th><th class="n">Amount</th><th>Nature</th><th>Borne by</th><th>Basis</th></tr>${im.rows.map(([n, v, nat, b, cc, f]) => `<tr class="${nat == 'contractual' ? 'mu' : ''}"><td>${n}</td><td class="n">${money(v)}</td><td>${bd(nat, nat == 'direct' ? 'wn' : nat == 'contractual' ? '' : 'in')}</td><td>${b}</td><td class="sm mu">${esc(f)}</td></tr>`).join('')}</table>
  <div class="kp" style="margin-top:8px">${Object.entries(by).map(([b, v]) => kpiTile('Borne by ' + b, mk(v), b == 'Airport' ? 'airport expense' : 'not an airport expense', '', b == 'Airport' ? 'neg' : '')).join('')}${kpiTile('Airport expense', mk(by.Airport || 0), im.A.contingent ? 'contingent memo ' + mk(im.direct) : 'only if cause is the airport\'s')}${kpiTile('Possible recovery', mk(im.reimb), 'estimate')}</div>
  <p class="note">Departure delay ≈ ${im.delay} min, aircraft down ≈ ${Math.round(im.down)} min. Stand charges (grey) are airport revenue already billed once in the ledger — listed for reference, never added twice.</p>`};
LIVE.dfTab = () => S.defects.length ? `<table><tr><th>Work order</th><th>Aircraft</th><th>Failure</th><th>Status</th><th>Cause</th><th>Responsible</th><th class="n">Airport expense</th><th class="n">Airline expense</th><th class="n">Other parties</th><th class="n">Recovery (est.)</th><th class="n">Stand charges</th></tr>${S.defects.map(d => {const r = S.rot[d.r], im = defectImpact(S, d), by = dfSplit(im), oth = Object.entries(by).filter(([b]) => b != 'Airport' && b != 'Airline').reduce((a, [, v]) => a + v, 0);
  return `<tr class="r" onclick="inspect('def','${d.id}')"><td><b>${d.wo}</b><div class="mu sm">${loc(d.t)} · by ${esc(d.by)}</div></td><td>${fid(r)} ${r.reg}</td><td class="sm">${d.name}</td><td>${bd(d.status, /RELEASED/.test(d.status) ? 'ok' : 'wn')}</td><td class="sm">${d.cause}</td><td class="sm">${im.A.bearer}${im.A.contingent ? ' <span class="neg">(contingent: ' + im.A.contingent + ')</span>' : ''}</td><td class="n ${by.Airport ? 'neg' : ''}">${money(by.Airport || 0)}</td><td class="n">${money(by.Airline || 0)}</td><td class="n">${money(oth)}</td><td class="n mu">${money(im.reimb)}</td><td class="n mu">${money(im.rows.find(x => x[2] == 'contractual')[1])}</td></tr>`}).join('')}</table>` : '<div class="empty">No technical failures recorded yet</div>';

// ---------- 6 · Emergency Diversions ----------
const DVQ = {type: 'A330', hrs: 6, arff: 1, medical: 1, tr: ''};
function divQuote(q) { // mirrors divOnBlock / landingCharge / chargesOffBlock for an operation = 'diversion'
  const c = S.cfg, T = AC_TYPES[q.type], code = T.code, tr = q.tr || c.diversion.treatment, d = c.diversion, cfg2 = {...c, diversion: {...d, treatment: tr}}, S2 = {cfg: cfg2};
  const L = [], add = (n, amt, st, f) => L.push({n, usd: amt, st, f});
  const land0 = Math.max(c.landing.minUsd, T.mtow * c.landing.usdPerTonne) * (c.landing.mult.diversion || 1), [la, ls, ln] = divTreat(S2, land0); add('Landing charge', la, ls, `max(${c.landing.minUsd}, ${T.mtow} t × $${c.landing.usdPerTonne}) × ${c.landing.mult.diversion}${ln}`);
  const pk = parkingCalc(S2.cfg ? {cfg: cfg2, t: q.hrs * 60} : S, {onBlk: 0, type: q.type, op: 'diversion'}, q.hrs * 60), [pa, ps, pn] = divTreat(S2, pk.usd); add('Aircraft parking', pa, pk.usd ? ps : 'n/a', pk.formula + pn);
  const h0 = c.handler == 'airport' ? (tr == 'contracted' ? d.contractUsd : c.handling.usd[code]) : 0, [ha, hs] = divTreat(S2, h0); if (c.handler == 'airport') add('Ground handling', ha, hs, tr == 'contracted' ? `contract flat $${d.contractUsd}` : `code ${code} handling fee`);
  add('Additional diversion services', tr == 'contracted' ? d.contractUsd : d.extraServicesUsd, tr == 'waived' ? 'waived' : tr == 'deferred' ? 'deferred' : tr == 'disputed' ? 'disputed' : 'estimate', 'buses, passenger handling, coordination');
  const arffH = q.arff ? 2 * Math.max(.25, .5) : 0, cost = [['ARFF standby', arffH * c.arffUsdVehHr, `2 vehicles × ${(arffH / 2).toFixed(2)} h × $${c.arffUsdVehHr}`], ['Medical response', q.medical ? c.medicalUsdCall : 0, `$${c.medicalUsdCall} per call-out`], ['Handling labour', c.handler == 'airport' ? c.handling.costUsd[code] : 0, `code ${code} labour & consumables`]];
  const resp = (q.medical ? c.medicalUsdCall : 0) + (q.arff ? 2 * c.arffUsdVehHr * .5 : 0) + d.extraServicesUsd, recov = resp * d.recoveryPct / 100;
  const billed = L.reduce((a, l) => a + l.usd, 0), recognised = L.filter(l => RECOG.includes(l.st)).reduce((a, l) => a + l.usd, 0), uncertain = L.filter(l => ['estimate', 'deferred'].includes(l.st)).reduce((a, l) => a + l.usd, 0), costs = cost.reduce((a, x) => a + x[1], 0);
  const expected = recognised + uncertain * d.recoveryPct / 100;
  return {L, cost, billed, recognised, uncertain, costs, recov, expected, profitRec: recognised - costs, profitExp: expected - costs, tr}}
VIEWS['fin.diversion'] = {sub: 'Configurable handling, parking and service charges for emergency diversions — billed amounts, what is actually recognised, the airport\'s costs and the resulting profit or loss.',
  html: () => {const sel = (k, o) => `<select onchange="DVQ.${k}=this.value;live(true)">${o.map(x => Array.isArray(x) ? x : [x, x]).map(([v, n]) => `<option value="${v}" ${DVQ[k] == v ? 'selected' : ''}>${n}</option>`).join('')}</select>`;
    return `<div class="row" style="margin-bottom:12px"><button class="btn dg" onclick="fxInject('diversion')">Inject emergency diversion (accepted)</button><span class="sp"></span><button class="btn" onclick="go('saf','emerg')">Diversion workflow →</button></div>
    <div class="g" style="grid-template-columns:minmax(0,1fr) minmax(0,1fr)"><div class="card"><div class="ch">Diversion calculator</div><div class="calc"><label>Aircraft type${sel('type', Object.keys(AC_TYPES).map(k => [k, `${k} (code ${AC_TYPES[k].code})`]))}</label>
    <label>Time on stand (h)<input type="number" min="0" step=".5" value="${DVQ.hrs}" onchange="DVQ.hrs=+this.value;live(true)"></label>
    <label>ARFF standby${sel('arff', [['1', 'Yes'], ['0', 'No']])}</label><label>Medical response${sel('medical', [['1', 'Yes'], ['0', 'No']])}</label><label>Financial treatment${sel('tr', [['', 'Configured (' + S.cfg.diversion.treatment + ')'], 'standard', 'contracted', 'reduced', 'waived', 'deferred', 'disputed'])}</label></div>
    <div class="card cfg" style="margin-top:10px;padding:8px"><div class="ch">Diversion rates (illustrative)<span class="sp"></span><button class="btn pri" onclick="applyCfg()">Apply</button></div>${cfgForm(TF.find(g => g[0] == 'Emergency diversions')[1].filter(x => !Array.isArray(x[2])), 'Applies to diversions charged from now on.')}</div></div>
    <div class="card"><div class="ch">Result — revenue is not profit</div><div data-live="dvRes"></div></div></div>
    <div class="card" style="margin-top:12px"><div class="ch">Diversions handled today (simulated)</div><div data-live="dvTab" class="tw"></div></div>`}};
LIVE.dvRes = () => {const q = divQuote({...DVQ, arff: +DVQ.arff, medical: +DVQ.medical});
  return `<table><tr><th>Charge</th><th class="n">Gross</th><th>Status</th><th>Formula</th></tr>${q.L.map(l => `<tr><td>${l.n}</td><td class="n">${money(l.usd)}</td><td>${bd(l.st, RECOG.includes(l.st) ? 'ok' : '')}</td><td class="formula" style="white-space:normal">${esc(l.f)}</td></tr>`).join('')}<tr><td><b>Total gross charges</b></td><td class="n"><b>${money(q.billed)}</b></td><td colspan="2"></td></tr></table>
  <table style="margin-top:8px"><tr><th>Airport cost</th><th class="n">Amount</th><th>Basis</th></tr>${q.cost.map(([n, v, f]) => `<tr><td>${n}</td><td class="n">${money(v)}</td><td class="sm mu">${f}</td></tr>`).join('')}<tr><td><b>Total airport cost</b></td><td class="n"><b>${money(q.costs)}</b></td><td></td></tr></table>
  <div class="kp" style="margin-top:8px">${kpiTile('Gross charges', mk(q.billed), 'before financial treatment')}${kpiTile('Recognised revenue', mk(q.recognised), 'status accrued / invoiced / paid')}${kpiTile('Expected cash', mk(q.expected), 'recognised + ' + S.cfg.diversion.recoveryPct + '% of uncertain')}${kpiTile('Profit — recognised', mk(q.profitRec), 'recognised − airport cost', '', q.profitRec >= 0 ? 'pos' : 'neg')}${kpiTile('Profit — expected', mk(q.profitExp), 'expected cash − airport cost', '', q.profitExp >= 0 ? 'pos' : 'neg')}${kpiTile('Response-cost recovery', mk(q.recov), 'estimate — not recognised')}</div>
  <p class="note">Under “${q.tr}” treatment ${q.tr == 'standard' ? 'charges are estimates until the operator confirms payment, so they are not counted as revenue yet' : q.tr == 'waived' ? 'charges are waived under the emergency policy — the airport carries the cost' : q.tr == 'contracted' ? 'a flat contract applies; amounts stay estimates until invoiced' : 'charges stay outside recognised revenue until resolved'}. Gross charges ≠ recognised revenue ≠ profit.</p>`};
LIVE.dvTab = () => {const R = fxRows(S).filter(r => r.type == 'diversion'); return R.length ? `<table><tr><th>Diversion</th><th>Recognised revenue & airport costs</th><th>Uncertain / not recognised</th><th>Other parties</th><th class="n">Net airport impact</th></tr>${R.map(r => `<tr style="vertical-align:top" ${r.ref ? `class="r" onclick="inspect('${r.ref.k}','${r.ref.id}')"` : ''}><td><b>${esc(r.ev)}</b><div class="mu sm">${loc(r.t0)} ${r.open ? bd('open', 'in') : bd('closed')}</div></td><td>${r.lines.map(l => `<div class="sm"><span class="${l.usd < 0 ? 'neg' : 'pos'}">${l.usd >= 0 ? '+' : ''}${money(l.usd)}</span> ${esc(l.n)}</div>`).join('') || '<span class="mu sm">—</span>'}</td><td>${r.unc.map(l => `<div class="sm mu">${money(l.usd)} ${esc(l.n)}</div>`).join('') || '—'}</td><td class="sm">${r.sec.slice(1).map(esc).join('<br>') || '—'}</td><td class="n"><b class="${r.net < 0 ? 'neg' : 'pos'}">${money(r.net)}</b></td></tr>`).join('')}</table>` : '<div class="empty">No diversions yet — inject one above</div>'};

// ---------- 7 · Profit & Loss ----------
VIEWS['fin.pnl'] = {sub: 'Revenue, expenses and net result with cost breakdowns and trends by terminal and operational category. Cash, invoiced, receivable and estimated amounts are kept apart.',
  html: () => VIEWS['biz.pnl'].html() + `<div class="g g2" style="margin-top:12px"><div class="card"><div class="ch">Result by terminal / area</div><div data-live="plTerm" class="tw"></div></div><div class="card"><div class="ch">Hourly trend — revenue by category vs expenses</div><div data-live="plHour"></div></div></div>`};
function plByTerm() {const p = pnl(S), o = {}, g = k => o[k] || (o[k] = {rev: 0, cost: 0});
  for (const e of S.L) {if (e.kind == 'rev' && e.payee == 'Airport' && recog(e)) g(revTerm(e)).rev += e.usd; else if (e.kind == 'cost' && e.bearer == 'Airport') g(e.term || 'Airport-wide').cost += e.usd}
  for (const t in S.ccT) for (const k in S.ccT[t]) g(t).cost += S.ccT[t][k];
  const alloc = Object.values(o).reduce((a, x) => a + x.cost, 0); g('Airport-wide').cost += p.costTot - alloc; g('Airport-wide').rev -= p.provision; return o}
LIVE.plTerm = () => {const o = plByTerm(), ks = Object.keys(o).sort((a, b) => (o[b].rev + o[b].cost) - (o[a].rev + o[a].cost)), t = ks.reduce((a, k) => ({rev: a.rev + o[k].rev, cost: a.cost + o[k].cost}), {rev: 0, cost: 0});
  return `<table><tr><th>Terminal / area</th><th class="n">Revenue</th><th class="n">Expenses</th><th class="n">Net</th></tr>${ks.map(k => `<tr><td>${AREA_N[k] || k}</td><td class="n">${money(o[k].rev)}</td><td class="n">${money(o[k].cost)}</td><td class="n ${o[k].rev - o[k].cost < 0 ? 'neg' : 'pos'}">${money(o[k].rev - o[k].cost)}</td></tr>`).join('')}<tr><td><b>Total</b></td><td class="n"><b>${money(t.rev)}</b></td><td class="n"><b>${money(t.cost)}</b></td><td class="n"><b>${money(t.rev - t.cost)}</b></td></tr></table>
  <p class="note">Flight revenue follows the stand's terminal; metered costs follow their metering point. “Airport-wide” holds unallocated fixed costs, commercial income and the dispute provision, so the total equals the P&L operating result.</p>`};
LIVE.plHour = () => {const keys = REV_GROUPS.map(g => g[0]), rows = []; for (let t = 0; t < Math.min(S.t, DAY_END); t += 60) rows.push({x: pad(hourOf(t)), label: pad(hourOf(t)) + ':00', v: {}});
  for (const e of S.L) if (e.kind == 'rev' && e.payee == 'Airport' && recog(e)) {const r = rows[Math.floor(Math.max(0, e.t - 1) / 60)]; if (r) {const k = revGroupOf(e.cat); r.v[k] = (r.v[k] || 0) + e.usd}}
  const cost = []; let prev = 0; for (const x of S.snap) if (x.t % 60 == 0) {cost.push([x.t, x.cost - prev]); prev = x.cost}
  const costByHour = rows.map((r, i) => {const c = S.snap.find(x => x.t == (i + 1) * 60), c0 = i ? S.snap.find(x => x.t == i * 60) : {cost: 0}; return c && c0 ? c.cost - c0.cost : null});
  return stackBars('c-plh', rows, keys, keys.map((k, i) => `var(--s${i % 8 + 1})`), {names: keys, fy: v => mk(v)}) + `<table class="sm" style="margin-top:6px"><tr><td class="mu">Expenses per hour</td>${costByHour.map((c, i) => `<td class="n" title="${rows[i].label}">${c == null ? '' : mk(c)}</td>`).join('')}</tr></table>`};

// ---------- 8 · Financial Impact Simulator (what-if) ----------
const WI = {base: 'forecast', tv: 0, ta: 0, et: 0, mc: 0, sc: 0, fp: 0, pc: 0, trS: 30};
const WI_F = [['tv', 'Traffic volume', '%'], ['ta', 'Aircraft turnaround (stand) time', '%'], ['et', 'Energy tariffs (electricity & demand)', '%'], ['mc', 'Maintenance costs', '%'], ['sc', 'Staff costs', '%'], ['fp', 'Fuel price', '%'], ['pc', 'Passenger & security charge rates', '%'], ['trS', 'Traffic-driven share of electricity', '% (assumption)']];
function wiModel(B, w) { // B = a simulation state; every line keeps its formula
  syncUtilityCosts(B); const p = pnl(B), f = 1 + w.tv / 100, ta = w.ta / 100, out = [], pct = (n, v) => `${n} ${v >= 0 ? '+' : ''}${v}%`;
  const done = B.R.filter(r => r.onBlk != null && r.onBlk >= 0 && r.offBlk != null && r.offBlk >= 0);
  const dPark = done.filter(r => r.op != 'diversion').reduce((a, r) => {const d = r.offBlk - r.onBlk; return a + parkingCalc(B, r, r.onBlk + d * (1 + ta)).usd - parkingCalc(B, r, r.offBlk).usd}, 0);
  const dOv = done.filter(r => r.dep).reduce((a, r) => {const d = r.offBlk - r.onBlk, o1 = overstayCalc(B, r, r.onBlk + d * (1 + ta)), o0 = overstayCalc(B, r, r.offBlk); return a + (o1.status != 'waived' ? o1.usd : 0) - (o0.status != 'waived' ? o0.usd : 0)}, 0);
  for (const [k, v] of Object.entries(p.rev)) {let s = v, fo = '';
    switch (k) {
      case 'Landing charges': case 'Ground handling': case 'Baggage handling services': case 'Concessions (retail/F&B)': case 'Private aviation handling': case 'Aircraft servicing & fuel': case 'Diversion handling': s = v * f; fo = `${money(v)} × ${pct('traffic', w.tv)}`; break;
      case 'Passenger & security charges': s = v * f * (1 + w.pc / 100); fo = `${money(v)} × ${pct('traffic', w.tv)} × ${pct('rate', w.pc)}`; break;
      case 'Aircraft parking': s = Math.max(0, v + dPark) * f; fo = `(${money(v)} + ${money(dPark)} re-billed with stand time ${pct('', w.ta)} per aircraft) × ${pct('traffic', w.tv)}`; break;
      case 'Overstay / stand blocking': s = Math.max(0, v + dOv) * f; fo = `(${money(v)} + ${money(dOv)} re-billed overstay with stand time ${pct('', w.ta)}) × ${pct('traffic', w.tv)}`; break;
      case 'Boarding bridge & 400 Hz': s = v * (1 + ta) * f; fo = `${money(v)} × ${pct('stand time', w.ta)} × ${pct('traffic', w.tv)} (hourly charge)`; break;
      default: fo = 'not traffic-linked (contracts, reimbursements)'}
    out.push({kind: 'rev', n: k, b: v, s, fo})}
  out.push({kind: 'prov', n: 'Provision on disputed charges', b: -p.provision, s: -p.provision * f, fo: `${money(-p.provision)} × ${pct('traffic', w.tv)}`});
  for (const [k, v] of Object.entries(p.cost)) {let s = v, fo = 'fixed / event-driven — unchanged';
    switch (k) {
      case 'Electricity': case 'Electricity demand charge': s = v * (1 + w.et / 100) * (1 + w.trS / 100 * w.tv / 100); fo = `${money(v)} × ${pct('tariff', w.et)} × (1 + ${w.trS}% × ${w.tv}% traffic)`; break;
      case 'Water': s = v * (1 + .5 * w.tv / 100); fo = `${money(v)} × (1 + 50% occupancy-driven × ${w.tv}%)`; break;
      case 'Ground vehicle fuel': s = v * (1 + w.fp / 100) * f; fo = `${money(v)} × ${pct('fuel price', w.fp)} × ${pct('traffic', w.tv)}`; break;
      case 'Staff costs': s = v * (1 + w.sc / 100); fo = `${money(v)} × ${pct('staff', w.sc)}`; break;
      case 'Ground handling costs': s = v * f * (1 + .5 * ta); fo = `${money(v)} × ${pct('traffic', w.tv)} × (1 + 50% time-based labour × ${w.ta}%)`; break;
      case 'Facility maintenance': case 'Baggage system maintenance': case 'Aircraft repair & downtime': s = v * (1 + w.mc / 100); fo = `${money(v)} × ${pct('maintenance', w.mc)}`; break;
      case 'Equipment maintenance (GSE)': s = v * (1 + w.mc / 100) * f; fo = `${money(v)} × ${pct('maintenance', w.mc)} × ${pct('traffic', w.tv)}`; break;
      case 'Cleaning & waste services': case 'Waste management': s = v * f; fo = `${money(v)} × ${pct('traffic', w.tv)}`; break}
    out.push({kind: 'cost', n: k, b: -v, s: -s, fo})}
  const tot = (k, x) => out.filter(l => k.includes(l.kind)).reduce((a, l) => a + l[x], 0);
  return {lines: out, revB: tot(['rev', 'prov'], 'b'), revS: tot(['rev', 'prov'], 's'), costB: -tot(['cost'], 'b'), costS: -tot(['cost'], 's'), opB: tot(['rev', 'prov', 'cost'], 'b'), opS: tot(['rev', 'prov', 'cost'], 's')}}
const wiState = () => WI.base == 'forecast' ? BASE : S;
VIEWS['fin.whatif'] = {sub: 'Change turnaround time, energy tariffs, maintenance costs, traffic volume and other assumptions and see the operating result change — every line shows its formula.',
  html: () => `<div class="g" style="grid-template-columns:330px minmax(0,1fr)"><div class="card cfg"><div class="ch">Assumptions</div><div class="seg" style="margin-bottom:10px"><button class="${WI.base == 'forecast' ? 'on' : ''}" onclick="WI.base='forecast';renderPage()">Full-day forecast</button><button class="${WI.base == 'actual' ? 'on' : ''}" onclick="WI.base='actual';renderPage()">Simulated day so far</button></div>
    <table>${WI_F.map(([k, n, u]) => `<tr><td>${n}</td><td><input type="number" step="1" value="${WI[k]}" onchange="WI.${k}=+this.value;live(true)"></td><td class="mu sm">${u}</td></tr>`).join('')}</table>
    <div class="row" style="margin-top:8px"><button class="btn" onclick="Object.assign(WI,{tv:0,ta:0,et:0,mc:0,sc:0,fp:0,pc:0});renderPage()">Reset</button><button class="btn pri" onclick="wiEngine()">Validate with engine</button></div>
    <p class="note">Model = linear drivers on the baseline P&L; parking and overstay are re-billed aircraft by aircraft with the scaled stand time. “Validate” reruns the full simulation with the tariff, maintenance, staff, fuel and passenger-charge changes (traffic and turnaround are not engine inputs).</p><div id="wiOut"></div></div>
  <div class="g" style="align-content:start"><div data-live="wiKpi"></div><div class="card"><div class="ch">Result line by line</div><div data-live="wiTab" class="tw"></div></div><div class="card"><div class="ch">Sensitivity — operating result change for ±10% on each driver</div><div data-live="wiSens"></div></div></div></div>`};
LIVE.wiKpi = () => {const m = wiModel(wiState(), WI); return `<div class="kp">${kpiTile('Revenue', mk(m.revS), (m.revS - m.revB >= 0 ? '+' : '') + mk(m.revS - m.revB) + ' vs baseline')}${kpiTile('Operating expenses', mk(m.costS), (m.costS - m.costB >= 0 ? '+' : '') + mk(m.costS - m.costB) + ' vs baseline')}${kpiTile('Operating result — baseline', mk(m.opB), WI.base == 'forecast' ? 'full-day forecast' : 'to ' + loc(S.t))}${kpiTile('Operating result — scenario', mk(m.opS), (m.opS - m.opB >= 0 ? '+' : '') + mk(m.opS - m.opB), '', m.opS - m.opB >= 0 ? 'pos' : 'neg')}</div>`};
LIVE.wiTab = () => {const m = wiModel(wiState(), WI), row = l => `<tr><td style="padding-left:${l.kind == 'rev' ? 8 : 8}px">${l.n}</td><td class="n">${money(l.b)}</td><td class="n">${money(l.s)}</td><td class="n ${l.s - l.b < 0 ? 'neg' : l.s - l.b > 0 ? 'pos' : 'mu'}">${Math.abs(l.s - l.b) < .5 ? '—' : (l.s - l.b > 0 ? '+' : '') + money(l.s - l.b)}</td><td class="formula" style="white-space:normal">${esc(l.fo)}</td></tr>`;
  return `<table><tr><th>Line</th><th class="n">Baseline</th><th class="n">Scenario</th><th class="n">Change</th><th>Formula</th></tr><tr><td colspan="5"><b>Revenue</b></td></tr>${m.lines.filter(l => l.kind != 'cost').map(row).join('')}<tr><td colspan="5"><b>Operating expenses</b></td></tr>${m.lines.filter(l => l.kind == 'cost').map(row).join('')}
  <tr><td><b>Operating result</b></td><td class="n"><b>${money(m.opB)}</b></td><td class="n"><b>${money(m.opS)}</b></td><td class="n ${m.opS - m.opB < 0 ? 'neg' : 'pos'}"><b>${(m.opS - m.opB >= 0 ? '+' : '') + money(m.opS - m.opB)}</b></td><td></td></tr></table>`};
LIVE.wiSens = () => {const B = wiState(), b = wiModel(B, WI).opS, R = WI_F.filter(x => x[0] != 'trS').map(([k, n]) => [n, wiModel(B, {...WI, [k]: WI[k] + 10}).opS - b, wiModel(B, {...WI, [k]: WI[k] - 10}).opS - b]).sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]));
  return `<table><tr><th>Driver</th><th class="n">−10%</th><th class="n">+10%</th><th style="width:40%"></th></tr>${R.map(([n, up, dn]) => {const mx = Math.max(...R.map(r => Math.max(Math.abs(r[1]), Math.abs(r[2])))) || 1;
    return `<tr><td>${n}</td><td class="n ${dn < 0 ? 'neg' : 'pos'}">${(dn >= 0 ? '+' : '') + mk(dn)}</td><td class="n ${up < 0 ? 'neg' : 'pos'}">${(up >= 0 ? '+' : '') + mk(up)}</td><td><div style="position:relative;height:10px;background:var(--p2);border-radius:3px"><i style="position:absolute;left:50%;height:10px;border-radius:3px;${up >= 0 ? 'left:50%' : 'right:50%;left:auto'};width:${Math.abs(up) / mx * 50}%;background:${up >= 0 ? 'var(--ok)' : 'var(--cr)'}"></i></div></td></tr>`}).join('')}</table>`};
function wiEngine() {const c = deep(S.cfg), k = 1 + WI.et / 100, m = 1 + WI.mc / 100, s = 1 + WI.sc / 100;
  c.elec.peakEgp *= k; c.elec.offpeakEgp *= k; c.elec.demandEgpKwMonth *= k; for (const x of ['facilityUsdHr', 'bhsUsdRunHr', 'gseUsdOpHr', 'bhsFaultCalloutUsd']) c.maint[x] *= m; c.labourUsdHr *= m; c.gseRepairUsd *= m; c.gseRecoveryUsd *= m;
  for (const x in c.staff) c.staff[x][1] *= s; c.dieselEgpL *= 1 + WI.fp / 100; c.paxUsd *= 1 + WI.pc / 100; c.secUsd *= 1 + WI.pc / 100;
  const A = run(SEED, null, DAY_END, S.cfg), B = run(SEED, null, DAY_END, c), ma = wiModel(A, {...WI, tv: 0, ta: 0}); syncUtilityCosts(B); const pb = pnl(B);
  $('#wiOut').innerHTML = `<table style="margin-top:8px"><tr><th>Full day</th><th class="n">Model</th><th class="n">Engine rerun</th></tr><tr><td>Operating result</td><td class="n">${money(ma.opS)}</td><td class="n">${money(pb.op)}</td></tr><tr><td>Difference</td><td class="n" colspan="2">${money(pb.op - ma.opS)} (${(100 * Math.abs(pb.op - ma.opS) / Math.max(1, Math.abs(pb.op))).toFixed(2)}%)</td></tr></table>${WI.tv || WI.ta ? '<p class="note">Traffic and turnaround changes are model-only and were excluded from this comparison.</p>' : ''}`}

// ---------- 9 · Event impact register (from the earlier Energy & Finance module) ----------
VIEWS['fin.events'] = {sub: VIEWS['biz.impact'].sub, html: () => VIEWS['biz.impact'].html()};

// ---------- 10 · Transactions & Reports ----------
const TX = {q: '', kind: '', cat: '', st: '', party: '', per: 'all', from: '06:00', to: '24:00', acc: 1, min: ''};
const TX_PER = [['all', 'Whole simulated day'], ['1h', 'Last hour'], ['3h', 'Last 3 hours'], ['am', '06:00–12:00'], ['pm', '12:00–18:00'], ['ev', '18:00–24:00'], ['custom', 'Custom range']];
function txRange() {const p = TX.per; return p == '1h' ? [S.t - 60, S.t] : p == '3h' ? [S.t - 180, S.t] : p == 'am' ? [0, 360] : p == 'pm' ? [360, 720] : p == 'ev' ? [720, 1080] : p == 'custom' ? [hm2t(TX.from), TX.to == '24:00' || TX.to == '00:00' ? 1080 : hm2t(TX.to)] : [-1e9, 1e9]}
function txRows() {const [a, b] = txRange(), q = TX.q.trim().toLowerCase(), whole = TX.per == 'all' || (a <= 0 && b >= S.t);
  let L = S.L.filter(e => e.t >= a && e.t <= b);
  if (TX.acc && whole) L = L.concat(Object.entries(S.cc).map(([k, v], i) => ({id: 'ACC-' + (i + 1), t: S.t, kind: 'cost', cat: k, desc: 'Running accrual — ' + k + ' (metered / time-based)', bearer: 'Airport', usd: Math.round(v.usd * 100) / 100, status: 'accrued', formula: COSTF[k] ? COSTF[k](S)[0] : 'running accrual', acc: 1})));
  return L.filter(e => (!TX.kind || e.kind == TX.kind) && (!TX.cat || e.cat == TX.cat) && (!TX.st || e.status == TX.st) && (!TX.party || [e.payer, e.payee, e.bearer].includes(TX.party)) && (!TX.min || e.usd >= +TX.min)
    && (!q || [e.id, e.desc, e.cat, e.payer, e.payee, e.bearer, e.formula, e.rot && S.rot[e.rot] ? fid(S.rot[e.rot]) + ' ' + S.rot[e.rot].reg : ''].join(' ').toLowerCase().includes(q)))}
function txSum(L) {const r = {n: L.length, revA: 0, revO: 0, revX: 0, costA: 0, costO: 0}; for (const e of L) {if (e.kind == 'rev') e.payee == 'Airport' ? (recog(e) ? r.revA += e.usd : r.revX += e.usd) : r.revO += e.usd; else e.bearer == 'Airport' ? r.costA += e.usd : r.costO += e.usd} return r}
VIEWS['fin.tx'] = {sub: 'Every simulated charge and cost — searchable, filterable by period, category, status and party, and exportable. Running cost accruals (energy, staff, fixed contracts) are included so totals tie to the P&L.',
  html: () => {const cats = [...new Set(S.L.map(e => e.cat).concat(Object.keys(S.cc)))].sort(), parties = [...new Set(S.L.flatMap(e => [e.payer, e.payee, e.bearer]).filter(Boolean))].sort(), o = (k, list, all) => `<select onchange="TX.${k}=this.value;live(true)"><option value="">${all}</option>${list.map(x => Array.isArray(x) ? x : [x, x]).map(([v, n]) => `<option value="${esc(v)}" ${TX[k] == v ? 'selected' : ''}>${esc(n)}</option>`).join('')}</select>`;
    return `<div class="card"><div class="row"><input type="search" placeholder="Search ID, flight, registration, description, payer…" value="${esc(TX.q)}" oninput="TX.q=this.value;live(true)" style="min-width:280px">
    <select onchange="TX.per=this.value;renderPage()">${TX_PER.map(([k, n]) => `<option value="${k}" ${TX.per == k ? 'selected' : ''}>${n}</option>`).join('')}</select>${TX.per == 'custom' ? `<input type="time" value="${TX.from}" onchange="TX.from=this.value;live(true)"><span class="mu">to</span><input type="time" value="${TX.to == '24:00' ? '23:59' : TX.to}" onchange="TX.to=this.value;live(true)">` : ''}
    ${o('kind', [['rev', 'Revenue'], ['cost', 'Cost']], 'All types')}${o('cat', cats, 'All categories')}${o('st', ['accrued', 'invoiced', 'paid', 'estimate', 'disputed', 'waived', 'deferred'], 'All statuses')}${o('party', parties, 'All parties')}
    <input type="number" placeholder="Min USD" value="${TX.min}" onchange="TX.min=this.value;live(true)" style="width:90px"><label class="sm"><input type="checkbox" ${TX.acc ? 'checked' : ''} onchange="TX.acc=this.checked?1:0;live(true)"> running accruals</label>
    <span class="sp"></span><button class="btn" onclick="txCsv()">Export filtered (CSV)</button></div><p class="note" style="margin:6px 0 0">The simulation covers one operating day (06:00–24:00 local); periods filter by the simulated posting time. Running accruals have no single posting time, so they appear only when the period covers the whole day so far.</p></div>
    <div data-live="txKpi" style="margin-top:12px"></div><div class="card" style="margin-top:12px"><div data-live="txTab" class="tw" style="max-height:60vh"></div></div>
    <div class="card" style="margin-top:12px"><div class="ch">Reports</div><div class="row">${FIN_RPT.map(([k, n]) => `<button class="btn" onclick="finRpt('${k}')">${n}</button>`).join('')}<button class="btn" onclick="rptFull()">Energy report (CSV)</button></div><p class="note">Every export is labelled as simulated data with illustrative tariffs.</p></div>`}};
LIVE.txKpi = () => {const s = txSum(txRows()); return `<div class="kp">${kpiTile('Records', s.n)}${kpiTile('Airport revenue (recognised)', mk(s.revA))}${kpiTile('Airport revenue (not recognised)', mk(s.revX), 'estimate / waived / deferred')}${kpiTile('Airport costs', mk(s.costA))}${kpiTile('Net (filtered)', mk(s.revA - s.costA), '', '', s.revA - s.costA >= 0 ? 'pos' : 'neg')}${kpiTile('Other parties', mk(s.revO + s.costO), 'revenue + costs, excluded')}</div>`};
LIVE.txTab = () => {const L = txRows().slice().sort((a, b) => b.t - a.t || (b.id > a.id ? 1 : -1)), shown = L.slice(0, 300);
  return `<table><tr><th>ID</th><th>Time</th><th>Type</th><th>Category</th><th>Description</th><th>Flight</th><th>Payer → receiver / bearer</th><th class="n">Amount</th><th>Status</th><th>Formula</th></tr>${shown.map(e => {const r = S.rot[e.rot];
    return `<tr${r ? ` class="r" onclick="inspect('rot','${r.id}')"` : ''}><td class="mu">${e.id}</td><td>${e.acc ? 'running' : loc(e.t)}</td><td>${e.kind == 'rev' ? bd('revenue', 'ok') : bd(e.acc ? 'accrual' : 'cost', 'wn')}</td><td class="sm">${e.cat}</td><td class="sm">${esc(e.desc)}</td><td class="sm">${r ? fid(r) + ' ' + r.reg : '—'}</td><td class="sm">${e.kind == 'rev' ? esc(e.payer) + ' → ' + esc(e.payee) : esc(e.bearer)}</td><td class="n">${money(e.usd, 2)}</td><td>${bd(e.status, e.status == 'paid' ? 'ok' : e.status == 'disputed' ? 'cr' : ['waived', 'deferred', 'estimate'].includes(e.status) ? '' : 'in')}</td><td class="formula">${esc(e.formula)}</td></tr>`}).join('')}</table>${L.length > 300 ? `<p class="note">Showing 300 of ${L.length} — refine the filters or export to CSV for all.</p>` : ''}`};
function txCsv() {const L = txRows(); dl('cai_transactions.csv', '# CAI digital twin — SIMULATED transactions, illustrative tariffs, not actual airport accounts\n' + csvRow(['id', 'sim_time', 'type', 'category', 'description', 'flight', 'payer', 'receiver_or_bearer', 'usd', 'status', 'formula']) + '\n' + L.map(e => csvRow([e.id, e.acc ? 'running' : loc(e.t), e.kind, e.cat, e.desc, e.rot && S.rot[e.rot] ? fid(S.rot[e.rot]) : '', e.payer || '', e.payee || e.bearer, e.usd, e.status, e.formula])).join('\n'), 'text/csv')}
const FIN_RPT = [['pnl', 'P&L statement'], ['rev', 'Revenue by source & status'], ['opex', 'Operating expenses with formulas'], ['park', 'Parking & overstay register'], ['events', 'Event impact register'], ['term', 'Result by terminal']];
function finRpt(k) {const H = '# CAI digital twin — SIMULATED, illustrative tariffs, to ' + loc(S.t) + ', USD\n', p = pnl(S); syncUtilityCosts(S); let rows;
  if (k == 'pnl') rows = [['line', 'usd'], ...Object.entries(p.rev).map(([n, v]) => ['Revenue: ' + n, v]), ['Provision on disputed', -p.provision], ['Net revenue', p.net], ...Object.entries(p.cost).map(([n, v]) => ['Cost: ' + n, -v]), ['Operating result', p.op]];
  else if (k == 'rev') rows = [['category', 'status', 'payer', 'usd']].concat(Object.values(S.L.filter(e => e.kind == 'rev' && e.payee == 'Airport').reduce((a, e) => {const key = e.cat + '|' + e.status + '|' + e.payer; (a[key] = a[key] || [e.cat, e.status, e.payer, 0])[3] += e.usd; return a}, {})));
  else if (k == 'opex') rows = [['category', 'usd', 'nature', 'formula', 'assumptions']].concat(Object.entries(p.cost).map(([n, v]) => {const F = COSTF[n] ? COSTF[n](S) : ['see ledger', '']; return [n, v, isVar(n) ? 'variable' : 'fixed', F[0], F[1]]}));
  else if (k == 'park') rows = [['flight', 'reg', 'stand', 'on_block', 'off_block', 'parking_usd', 'overstay_usd', 'overstay_status', 'responsible']].concat(S.R.filter(r => r.onBlk != null && r.onBlk >= 0).map(r => {const L = S.L.filter(e => e.rot == r.id), pk = L.find(e => e.cat == 'Aircraft parking'), ov = L.find(e => e.cat == 'Overstay / stand blocking'); return [fid(r), r.reg, r.stand, loc(r.onBlk), r.offBlk != null ? loc(r.offBlk) : 'on stand', pk ? pk.usd : 0, ov ? ov.usd : 0, ov ? ov.status : '', r.dep ? overstayCalc(S, r, r.offBlk ?? S.t).party : '']}));
  else if (k == 'events') rows = [['event', 'start', 'direct_items', 'secondary', 'responsible', 'cost_centre', 'net_usd', 'uncertain_usd']].concat(fxRows(S, BASE).map(r => [r.ev, loc(r.t0), r.lines.map(l => l.n + ' ' + l.usd.toFixed(0)).join('; '), r.sec.join('; '), r.resp, r.cc, r.net, r.uncT]));
  else {const o = plByTerm(); rows = [['area', 'revenue', 'expenses', 'net']].concat(Object.entries(o).map(([a, v]) => [a, v.rev, v.cost, v.rev - v.cost]))}
  dl('cai_' + k + '_report.csv', H + rows.map(r => csvRow(r.map(v => typeof v == 'number' ? v.toFixed(2) : v))).join('\n'), 'text/csv')}

// ---------- 11 · Rates, Fees & Currency ----------
VIEWS['fin.config'] = {sub: 'Rates, fees, currencies and financial assumptions. Editable only by authorised roles; every change is audited. All defaults are ILLUSTRATIVE — verify against official tariffs and contracts before any real use.',
  html: () => `<div class="g g3"><div class="card"><div class="ch">Your access</div><table class="sm"><tr><td>Role</td><td><b>${role}</b></td></tr><tr><td>Financial rates & fees</td><td>${canCfgK('fin') ? bd('EDIT', 'ok') : bd('READ-ONLY')}</td></tr><tr><td>Energy tariffs & ratings</td><td>${canCfgK('en') ? bd('EDIT', 'ok') : bd('READ-ONLY')}</td></tr></table><p class="note">Financial rates: ${CFG_ROLES.fin.join(', ')}. Energy tariffs: ${CFG_ROLES.en.join(', ')}. Demo permissions — not real access control.</p></div>
    <div class="card cfg"><div class="ch">Currency</div><div class="row" style="margin-bottom:8px"><span class="sm mu">Display</span>${curSeg()}</div>${cfgForm([['fx', 'Egyptian pound', 'EGP per USD'], ['eurPerUsd', 'Euro', 'EUR per USD']], 'Amounts are calculated in USD and converted for display at these rates (assumptions). <button class="btn pri" onclick="applyCfg()">Apply rates</button>')}</div>
    <div class="card cfg"><div class="ch">Configurable revenue streams<span class="sp"></span><button class="btn" onclick="cusAdd()" ${cfgDis('custom')}>+ Add</button></div><div data-live="cusTab"></div></div></div>
  <div style="margin-top:12px">${VIEWS['biz.tariffs'].html()}</div>
  <div class="card" style="margin-top:12px"><div class="ch">Rate change audit</div><div data-live="cfgAudit" class="tw"></div></div>`};
LIVE.cusTab = () => {const d = cfgDis('custom'); return `<table>${(S.cfg.custom || []).map((x, i) => `<tr><td><input value="${esc(x.name)}" data-c="${i}.name" ${d}></td><td><input value="${esc(x.payer)}" data-c="${i}.payer" ${d} style="width:110px"></td><td><input type="number" value="${x.usdDay}" data-c="${i}.usdDay" ${d} style="width:80px"></td><td><button class="btn" onclick="cusDel(${i})" ${d}>✕</button></td></tr>`).join('')}<tr class="mu sm"><td>Name</td><td>Payer</td><td>USD / day</td><td></td></tr></table><div class="row" style="margin-top:6px"><button class="btn pri" onclick="cusSave()" ${d}>Save streams</button></div><p class="note">Posted hourly to the ledger as “Other commercial” revenue (accrued) from the next hour.</p>`};
function cusSave() {if (!can() || !canCfgK('fin')) return toast('Your role cannot change revenue streams'); for (const el of document.querySelectorAll('[data-c]')) {const [i, k] = el.dataset.c.split('.'), x = S.cfg.custom[+i]; if (!x) continue; const v = k == 'usdDay' ? Math.max(0, +el.value) : el.value.trim(); if (x[k] !== v) {audit(`Tariff custom stream ${x.name} ${k}: ${x[k]} → ${v}`); x[k] = v}} toast('Revenue streams saved'); live(true)}
function cusAdd() {if (!can() || !canCfgK('fin')) return toast('Your role cannot change revenue streams'); S.cfg.custom.push({name: 'New stream', payer: 'Customer', usdDay: 0}); audit('Tariff custom stream added'); renderPage()}
function cusDel(i) {if (!can() || !canCfgK('fin')) return toast('Your role cannot change revenue streams'); const x = S.cfg.custom.splice(i, 1)[0]; audit(`Tariff custom stream removed: ${x.name}`); renderPage()}
LIVE.cfgAudit = () => {const l = S.au.filter(a => /^Tariff|^Refused/.test(a.m)); return l.length ? `<table><tr><th>Sim time</th><th>Role</th><th>Change</th></tr>${l.slice(0, 50).map(a => `<tr><td>${loc(a.t)}</td><td>${a.role}</td><td class="sm">${esc(a.m)}</td></tr>`).join('')}</table>` : '<div class="empty">No rate changes yet</div>'};
